function X = gjinv(A)
    [m, n] = size(A);
    if m ~= n
        error('Input matrix must be square.');
    end
    Aug = [double(A), eye(n)];
    for k = 1:n
        % 按列选主元：在第 k 列第 k..n 行中选绝对值最大元
        [max_val, rel_idx] = max(abs(Aug(k:n, k)));
        if max_val == 0
            error('Matrix is singular.');
        end
        piv = k + rel_idx - 1;
        if piv ~= k
            Aug([k, piv], :) = Aug([piv, k], :);
        end
        % 主元行归一化并消去第 k 列其余所有元素
        Aug(k, :) = Aug(k, :) / Aug(k, k);
        for i = 1:n
            if i ~= k && Aug(i, k) ~= 0
                Aug(i, :) = Aug(i, :) - Aug(i, k) * Aug(k, :);
            end
        end
    end
    X = Aug(:, n+1:end);
end
```

