function [L, U] = mylu(A)
    [m, n] = size(A);
    if m ~= n
        error('Input matrix must be square.');
    end
    U = double(A);
    L = eye(n);
    for k = 1:n-1
        if U(k, k) == 0
            error('Zero pivot encountered at step %d.', k);
        end
        for i = k+1:n
            L(i, k) = U(i, k) / U(k, k);
            U(i, k:n) = U(i, k:n) - L(i, k) * U(k, k:n);
        end
    end
end
